#include <gtest/gtest.h>
extern "C" {
#include "safe.h"        // ren C-logik utan <avr/io.h>
}

TEST(SafeStateMachine, CorrectCodeUnlocksTheSafe) {
    // Arrange
    SafeState s = STATE_IDLE;
    // Act
    s = nextState(s, '1');
    s = nextState(s, '2');
    s = nextState(s, '3');
    s = nextState(s, '4');
    // Assert
    EXPECT_EQ(s, STATE_UNLOCKED);
}

TEST(SafeStateMachine, WrongDigitGoesBackToIdle) {
    EXPECT_EQ(nextState(STATE_12, '9'), STATE_IDLE);
}

